
.experience-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 100%;
}

.summary {
  display: flex;
  gap: 8px;
}

.level-card,
.stat-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 10px 4px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
}

.level-badge {
  padding: 2px 12px;
  border-radius: 12px;
  background: rgba(224, 107, 158, 0.18);
  color: var(--c-accent);
  font-weight: 700;
  font-size: 14px;
}

.level-label,
.stat-label {
  font-size: 11px;
  color: var(--c-text-dim);
}

.stat-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--c-accent);
}

.block {
  flex: 1;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--c-border);
  border-radius: 6px;
  background: var(--c-surface);
  overflow: hidden;
}

.block-title {
  padding: 6px 10px;
  font-size: 12px;
  color: var(--c-text-dim);
  background: var(--c-surface-2);
  border-bottom: 1px solid var(--c-border);
}

.row {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px 10px;
}

.value.dim {
  color: var(--c-text-dim);
}

.record {
  padding: 8px 10px;
  border-bottom: 1px solid var(--c-border);
}

.record:last-child {
  border-bottom: none;
}

.record-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 8px;
}

.record-time {
  color: var(--c-text);
  font-weight: 600;
}

.record-place {
  color: var(--c-accent);
}

.record-meta {
  color: var(--c-text-dim);
  font-size: 12px;
}

.record-result {
  color: var(--c-safe);
  font-size: 12px;
}

.record-recall {
  margin-top: 4px;
  color: var(--c-text-dim);
  font-size: 12px;
  line-height: 1.5;
}
