
.overview-panel {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  padding: 14px 12px;
}

.name {
  font-size: 18px;
  font-weight: 700;
  color: var(--c-accent);
  letter-spacing: 1px;
}

.time {
  font-size: 13px;
  color: var(--c-text-dim);
}

.item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.label {
  font-size: 11px;
  color: var(--c-text-dim);
}

.value {
  color: var(--c-text);
  font-size: 14px;
  line-height: 1.4;
  word-break: break-all;
}

.arousal {
  display: flex;
  align-items: center;
  gap: 8px;
}

.arousal .value {
  font-size: 20px;
  font-weight: 700;
  color: var(--c-accent);
  min-width: 2ch;
}

.bar {
  flex: 1;
  height: 6px;
  border-radius: 3px;
  background: var(--c-surface-2);
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--c-accent-2), var(--c-accent));
  transition: width 0.3s ease;
}
